package location

import (
	"context"
)

// Location contains data about a location.
type Location struct {
	ID          int64  `json:"id"`
	Name        string `json:"name"`
	Coordinates string `json:"coordinates"`
}

// Interface exposed by the Location service.
type Interface interface {
	Get(ctx context.Context, locationID int) (*Location, error)
	List(ctx context.Context) ([]Location, error)
	Put(ctx context.Context, location *Location) error
}

package location

import (
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"strconv"
	"time"

	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/baggageutils"
	"github.com/signadot/hotrod/pkg/config"
	"github.com/signadot/hotrod/pkg/httperr"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/notifications"
	"github.com/signadot/hotrod/pkg/tracing"
)

// Server implements Location service
type Server struct {
	addr           string
	tracerProvider trace.TracerProvider
	logger         log.Factory
	notification   notifications.Interface
	database       *database
}

// NewServer creates new location.Server
func NewServer(logger log.Factory) *Server {
	// get tracer provider for the location
	tracerProvider := tracing.InitOTEL("location", logger)

	return &Server{
		addr:           net.JoinHostPort("0.0.0.0", config.GetLocationBindPort()),
		tracerProvider: tracerProvider,
		logger:         logger,
		database:       newDatabase(logger),
		notification:   notifications.NewNotificationHandler(tracerProvider, logger),
	}
}

// Run starts the Location server
func (s *Server) Run() error {
	mux := s.createServeMux()
	s.logger.Bg().Info("Starting", zap.String("address", "http://"+s.addr))
	server := &http.Server{
		Addr:              s.addr,
		Handler:           mux,
		ReadHeaderTimeout: 3 * time.Second,
	}
	return server.ListenAndServe()
}

func (s *Server) createServeMux() http.Handler {
	mux := tracing.NewServeMux(false, s.tracerProvider, s.logger)
	mux.Handle("GET /locations", http.HandlerFunc(s.listLocations))
	mux.Handle("GET /location", http.HandlerFunc(s.getLocation))
	mux.Handle("POST /location", http.HandlerFunc(s.createLocation))
	mux.Handle("DELETE /location", http.HandlerFunc(s.deleteLocation))
	mux.Handle("GET /healthz", http.HandlerFunc(func(resp http.ResponseWriter, req *http.Request) {
		s.logger.For(req.Context()).Info("/healthz")
		resp.Write([]byte("ok"))
	}))
	return mux
}

func (s *Server) listLocations(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))
	locations, err := s.database.List(ctx)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("cannot get locations", zap.Error(err))
		return
	}

	data, err := json.Marshal(locations)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("cannot marshal response", zap.Error(err))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

func (s *Server) getLocation(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))
	if err := r.ParseForm(); httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	locationID, err := parseLocationID(r)
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	response, err := s.database.Get(ctx, locationID)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("request failed", zap.Error(err))
		return
	}

	data, err := json.Marshal(response)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("cannot marshal response", zap.Error(err))
		return
	}

	// extract the request context
	reqContext, err := baggageutils.ExtractRequestContext(ctx)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("cannot extract request context from baggage", zap.Error(err))
		return
	}
	if reqContext != nil {
		// send a notification
		s.notification.Store(ctx, &notifications.Notification{
			ID:        fmt.Sprintf("req-%d-location-resolve", reqContext.ID),
			Timestamp: time.Now(),
			Context:   s.notification.NotificationContext(reqContext, baggageutils.GetRoutingKey(ctx)),
			Body:      "Resolving locations",
		})
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

func (s *Server) createLocation(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	// decode the request body
	var loc Location
	err := json.NewDecoder(r.Body).Decode(&loc)
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	// create the location
	loc.ID, err = s.database.Create(ctx, &loc)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("request failed", zap.Error(err))
		return
	}

	// marshal response
	data, err := json.Marshal(loc)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("cannot marshal response", zap.Error(err))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

func (s *Server) deleteLocation(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))
	if err := r.ParseForm(); httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	locationID, err := parseLocationID(r)
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	err = s.database.Delete(ctx, locationID)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("request failed", zap.Error(err))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("{}"))
}

func parseLocationID(r *http.Request) (int, error) {
	locationIDStr := r.Form.Get("locationID")
	if locationIDStr == "" {
		return 0, errors.New("missing required 'locationID' parameter")
	}
	locationID, err := strconv.Atoi(locationIDStr)
	if err != nil {
		return 0, errors.New("parameter 'locationID' is not an integer")
	}
	return locationID, nil
}
	"github.com/signadot/hotrod/pkg/config"
	"github.com/signadot/hotrod/pkg/delay"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/tracing"
)

// database implements a Location repository on top of an SQL database
type database struct {
	tracer trace.Tracer
	logger log.Factory
	lock   *tracing.Mutex
	db     *sqlx.DB
}

const tableSchema = `
CREATE TABLE IF NOT EXISTS locations
(
    id bigint unsigned NOT NULL AUTO_INCREMENT,
    name varchar(255) NOT NULL,
    coordinates varchar(255) NOT NULL,

    PRIMARY KEY (id),
	UNIQUE KEY name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
`

var seed = []Location{
	{
		ID:          1,
		Name:        "My Home",
		Coordinates: "231,773",
	},
	{
		ID:          123,
		Name:        "Rachel's Floral Designs",
		Coordinates: "115,277",
	},
	{
		ID:          567,
		Name:        "Amazing Coffee Roasters",
		Coordinates: "211,653",
	},
	{
		ID:          392,
		Name:        "Trom Chocolatier",
		Coordinates: "577,322",
	},
	{
		ID:          731,
		Name:        "Japanese Desserts",
		Coordinates: "728,326",
	},
}

func newDatabase(logger log.Factory) *database {
	logger = logger.With(zap.String("component", "database"))

	var (
		db  *sqlx.DB
		err error
	)
	ticker := time.NewTicker(time.Second / 3)
	defer ticker.Stop()
	for {
		db, err = sqlx.ConnectContext(context.TODO(), "mysql", driverConfig().FormatDSN())
		if err == nil {
			break
		}
		logger.Bg().Error("error connecting to db", zap.Error(err))
		<-ticker.C
	}

	return &database{
		tracer: tracing.InitOTEL("mysql", logger).Tracer("mysql"),
		logger: logger,
		lock: &tracing.Mutex{
			SessionBaggageKey: "request",
		},
		db: db,
	}
}

func driverConfig() *mysql.Config {
	dc := mysql.NewConfig()
	dc.Net = "tcp"
	dc.Addr = config.GetMySQLAddr()
	dc.DBName = config.GetMySQLDatabaseName()
	dc.User = config.GetMySQLUser()
	dc.Passwd = config.GetMySQLPassword()

	dc.Timeout = 60 * time.Second
	dc.InterpolateParams = true
	dc.ParseTime = true
	dc.Params = map[string]string{
		"time_zone": "'+00:00'",
	}
	return dc
}

func (d *database) List(ctx context.Context) ([]Location, error) {
	d.logger.For(ctx).Info("Loading locations", zap.String("location-id", "*"))
	// simulate opentracing instrumentation of an SQL query

	_, span := d.tracer.Start(ctx, "SQL SELECT", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.PeerServiceKey.String("mysql"),
		attribute.
			Key("sql.query").
			String("SELECT id, name, coordinates FROM locations"),
	)
	defer span.End()

	query := "SELECT id, name, coordinates FROM locations"
	rows, err := d.db.Query(query)
	if err != nil {
		if !d.shouldRetry(err) {
			return nil, err
		}
		rows, err = d.db.Query(query)
		if err != nil {
			return nil, err
		}
	}
	defer rows.Close()
	var cs []Location
	for rows.Next() {
		c := Location{}
		if err := rows.Scan(&c.ID, &c.Name, &c.Coordinates); err != nil {
			return nil, err
		}
		cs = append(cs, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	return cs, nil
}

func (d *database) Create(ctx context.Context, location *Location) (int64, error) {
	query := "INSERT INTO locations SET name = ?, coordinates = ?"
	res, err := d.db.Exec(query, location.Name, location.Coordinates)
	if err != nil {
		if !d.shouldRetry(err) {
			return 0, err
		}
		res, err = d.db.Exec(query, location.Name, location.Coordinates)
		if err != nil {
			return 0, err
		}
	}
	id, err := res.LastInsertId()
	if err != nil {
		return 0, err
	}
	return id, nil
}

func (d *database) Update(ctx context.Context, location *Location) error {
	query := "UPDATE locations SET name = ?, coordinates = ? WHERE id = ?"
	res, err := d.db.Exec(query, location.Name, location.Coordinates, location.ID)
	if err != nil {
		if !d.shouldRetry(err) {
			return err
		}
		res, err = d.db.Exec(query, location.Name, location.Coordinates, location.ID)
		if err != nil {
			return err
		}
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n != 1 {
		return fmt.Errorf("wrong number of rows on update: %d != 1", n)
	}
	return nil
}

func (d *database) Get(ctx context.Context, locationID int) (*Location, error) {
	d.logger.For(ctx).Info("Loading location", zap.Int("location_id", locationID))

	_, span := d.tracer.Start(ctx, "SQL SELECT", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.PeerServiceKey.String("mysql"),
		attribute.
			Key("sql.query").
			String(fmt.Sprintf("SELECT id, name, coordinates from locations WHERE id = %d", locationID)),
	)
	defer span.End()

	// if !config.MySQLMutexDisabled {
	// 	// simulate misconfigured connection pool that only gives one connection at a time
	// 	d.lock.Lock(ctx)
	// 	defer d.lock.Unlock()
	// }

	// simulate RPC delay
	delay.Sleep(config.GetMySQLGetDelay(), config.GetMySQLGetDelayStdDev())

	var c Location
	query := "SELECT id, name, coordinates FROM locations WHERE id = ?"
	row := d.db.QueryRow(query, locationID)
	if row.Err() != nil {
		if !d.shouldRetry(row.Err()) {
			return nil, row.Err()
		}
		row = d.db.QueryRow(query, locationID)
		if row.Err() != nil {
			return nil, row.Err()
		}
	}
	if err := row.Scan(&c.ID, &c.Name, &c.Coordinates); err != nil {
		return nil, err
	}
	return &c, nil
}

func (d *database) Delete(ctx context.Context, locationID int) error {
	query := "DELETE FROM locations WHERE id = ?"
	_, err := d.db.Exec(query, locationID)
	if err != nil {
		if !d.shouldRetry(err) {
			return err
		}
		err = nil
	}
	return err
}

func (d *database) shouldRetry(err error) bool {
	if mysqlErr, ok := err.(*mysql.MySQLError); ok {
		switch mysqlErr.Number {
		case 1146:
			// this is a "Table doesn't exist"
			d.setupDB()
			return true
		}
	}
	return false
}

func (d *database) setupDB() {
	// Create the table
	fmt.Println("creating locations table")
	_, err := d.db.Exec(tableSchema)
	if err != nil {
		panic(err)
	}

	fmt.Println("seeding database")
	stmt, err := d.db.Prepare("INSERT INTO locations (id, name, coordinates) VALUES (?, ?, ?)")
	if err != nil {
		panic(err)
	}
	for i := range seed {
		c := &seed[i]
		if _, err := stmt.Exec(c.ID, c.Name, c.Coordinates); err != nil {
			panic(err)
		}
	}
	stmt.Close()
}


